const today = $now.toFormat('dd/MM/yyyy');
const rawSites = ($input.first().json.data ?? $input.first().json ?? '').toString();
const sites = rawSites.split(/\r?\n/)
  .map(function (l) { return l.trim(); })
  .filter(function (l) { return l && !l.startsWith('#'); });
const sitesLine = sites.length
  ? ' Cherche en priorite sur les sites suivants (en plus de toute autre source pertinente si besoin) : ' + sites.join(', ') + '.'
  : '';

const prompt = 'Nous sommes le ' + today + '. Tu es un redacteur culturel. Utilise la recherche web pour trouver les expositions et evenements lies a l\'art (expositions, vernissages, biennales, galeries, musees, centres d\'art) qui, a la date d\'aujourd\'hui, sont soit deja accessibles soit prevus dans les prochaines semaines, a Rennes et dans le departement Ille-et-Vilaine (35), en Bretagne, France.' + sitesLine + ' Pour chaque evenement distinct que tu retiens, ecris un paragraphe separe donnant : le nom de l\'evenement, le nom exact du lieu, la ville, l\'adresse si tu la connais, les dates precises, une description en 1-2 phrases, et cite la page web qui te sert de source pour cette information. Important concernant les sources : pour chaque evenement, cherche et cite en priorite la page dediee a cet evenement precis (la fiche de l\'exposition sur le site du lieu, un article qui parle specifiquement de cet evenement) plutot que la page d\'accueil du site ou une simple liste generale d\'agenda ; si necessaire, fais une recherche additionnelle avec le nom de l\'evenement et le nom du lieu pour trouver cette page dediee. Utilise la page d\'accueil ou une liste d\'agenda uniquement en dernier recours, si vraiment aucune page dediee n\'existe. Verifie via la recherche web que chaque evenement est reel et que ses dates sont a jour. Si tu ne trouves aucune information fiable, dis-le simplement. N\'invente jamais un evenement.';

const body = {
  model: 'gpt-4.1',
  tools: [{ type: 'web_search' }],
  input: prompt,
};

return [{ json: { body } }];

const response = $input.first().json;
const output = response.output || [];
let text = '';
let annotations = [];
for (const item of output) {
  if (item.type === 'message' && Array.isArray(item.content)) {
    for (const c of item.content) {
      if (c.type === 'output_text') {
        text = c.text || '';
        annotations = c.annotations || [];
      }
    }
  }
}

const sorted = annotations.filter(a => a.type === 'url_citation' && a.url).sort((a, b) => b.end_index - a.end_index);
for (const a of sorted) {
  const insert = ' (Source: ' + a.url + ')';
  text = text.slice(0, a.end_index) + insert + text.slice(a.end_index);
}

return [{ json: { annotated_text: text } }];

const text = $input.first().json.annotated_text || '';
const prompt = 'Voici un texte decrivant des expositions et evenements d\'art a Rennes et en Ille-et-Vilaine. Des mentions "(Source: URL)" indiquent l\'URL de la page web la plus proche pour l\'information qui precede. Extrait chaque evenement distinct decrit dans ce texte sous forme structuree selon le schema fourni. Pour le champ link, reprends telle quelle l\'URL "(Source: ...)" la plus proche et la plus pertinente pour cet evenement precis ; laisse une chaine vide si aucune URL claire n\'est associee a cet evenement. Choisis la categorie la plus precise possible ; n\'utilise exposition que si aucune autre categorie ne convient mieux. Determine le statut en_cours ou a_venir a partir des dates mentionnees dans le texte. Mets featured a true uniquement pour les evenements manifestement majeurs : grande institution (musee, Frac, centre d\'art reconnu), retrospective d\'envergure, biennale/triennale, ou evenement decrit dans le texte comme un temps fort ; mets featured a false pour tout le reste, y compris en cas de doute. Ne modifie aucun fait et n\'ajoute aucun evenement qui ne serait pas deja present dans le texte.\n\nTexte:\n' + text;

const body = {
  model: 'gpt-4.1',
  input: prompt,
  text: {
    format: {
      type: 'json_schema',
      name: 'exhibitions_list',
      strict: true,
      schema: {"type": "object", "properties": {"exhibitions": {"type": "array", "items": {"type": "object", "properties": {"title": {"type": "string"}, "category": {"type": "string", "enum": ["peinture", "sculpture", "photographie", "arts_numeriques", "street_art", "design", "spectacle_vivant", "exposition"]}, "venue": {"type": "string"}, "city": {"type": "string"}, "address": {"type": "string"}, "start_date": {"type": "string"}, "end_date": {"type": "string"}, "dates_label": {"type": "string"}, "status": {"type": "string", "enum": ["en_cours", "a_venir"]}, "description": {"type": "string"}, "link": {"type": "string"}, "featured": {"type": "boolean"}}, "required": ["title", "category", "venue", "city", "address", "start_date", "end_date", "dates_label", "status", "description", "link", "featured"], "additionalProperties": false}}}, "required": ["exhibitions"], "additionalProperties": false}
    }
  }
};

return [{ json: { body } }];

const response = $input.first().json;
let text = '';
const output = response.output || [];
for (const item of output) {
  if (item.type === 'message' && Array.isArray(item.content)) {
    for (const c of item.content) {
      if (c.type === 'output_text' && c.text) text += c.text;
    }
  }
}
if (!text && response.output_text) text = response.output_text;

text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
}

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {};
}
let items = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.exhibitions) ? parsed.exhibitions : []);

// Rejects homepage / generic listing-page links (e.g. leschampslibres.fr/
// or .../au-programme/recherche) — a link that just dumps the visitor on
// a search page instead of the specific event is worse than no link at
// all, so treat those the same as an invalid link (empty string).
// Deliberately avoids the URL constructor: n8n's Code node sandbox does
// not reliably expose it, which previously made every single link
// silently fail the try/catch and get rejected regardless of content.
function isLowValueLink(link) {
  const noFragment = link.split('#')[0];
  const noQuery = noFragment.split('?')[0];
  const afterProtocol = noQuery.replace(/^https?:\/\//i, '');
  const slashIdx = afterProtocol.indexOf('/');
  const path = slashIdx === -1 ? '' : afterProtocol.slice(slashIdx);
  const trimmed = path.replace(/\/+$/, '');
  if (trimmed === '') return true;
  const segments = trimmed.split('/').filter(Boolean);
  const last = (segments[segments.length - 1] || '').toLowerCase();
  const generic = ['recherche','search','agenda','actualites','actualite','programme','expositions','exposition','evenements','evenement','events','event','news','accueil','home','exhibitions','exhibition','activites','activite'];
  if (generic.includes(last)) return true;
  if (segments.length === 1 && /^[a-z]{2}$/.test(last)) return true;
  return false;
}

const validCategories = ['peinture','sculpture','photographie','arts_numeriques','street_art','design','spectacle_vivant','exposition'];
const cleaned = items
  .filter(it => it && it.title && it.venue)
  .map(it => {
    const link = (typeof it.link === 'string' && /^https?:\/\//i.test(it.link) && !isLowValueLink(it.link)) ? it.link : '';
    return {
      title: String(it.title),
      category: validCategories.includes(it.category) ? it.category : 'exposition',
      venue: String(it.venue),
      city: String(it.city || 'Rennes'),
      address: String(it.address || ''),
      start_date: String(it.start_date || ''),
      end_date: String(it.end_date || ''),
      dates_label: String(it.dates_label || ''),
      status: (it.status === 'en_cours' || it.status === 'a_venir') ? it.status : '',
      description: String(it.description || ''),
      link: link,
      featured: it.featured === true,
    };
  })
  // User preference: an event with no specific/direct source page is
  // dropped entirely rather than shown with an empty 'more info' link.
  .filter(it => it.link);

return [{ json: { exhibitions: cleaned } }];

const CATEGORIES = {
  peinture: { label: 'Peinture', icon: 'peinture', color: '#C1694F' },
  sculpture: { label: 'Sculpture', icon: 'sculpture', color: '#8C8577' },
  photographie: { label: 'Photographie', icon: 'photographie', color: '#5D80A3' },
  arts_numeriques: { label: 'Arts numeriques', icon: 'arts_numeriques', color: '#5F8B7A' },
  street_art: { label: 'Street art', icon: 'street_art', color: '#D3A048' },
  design: { label: 'Design', icon: 'design', color: '#B97A94' },
  spectacle_vivant: { label: 'Spectacle vivant', icon: 'spectacle_vivant', color: '#7C4A5B' },
  exposition: { label: 'Exposition', icon: 'exposition', color: '#A38F76' },
};

const exhibitions = $input.first().json.exhibitions || [];
const enCours = exhibitions.filter(e => e.status !== 'a_venir');
const aVenir = exhibitions.filter(e => e.status === 'a_venir');

function esc(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function chip(cat) {
  return '<img src="https://penloup.eu/art-actu-logos/' + cat.icon + '.png" width="22" height="22" alt="" style="display:inline-block;vertical-align:middle;border-radius:50%;">';
}

function renderList(list) {
  if (list.length === 0) return '<p style="font-family:Arial,sans-serif;color:#666;">Rien de confirme pour cette periode.</p>';
  return '<ul style="font-family:Arial,sans-serif;padding-left:20px;list-style:none;margin-left:0;">' + list.map(e => {
    const cat = CATEGORIES[e.category] || CATEGORIES.exposition;
    const star = e.featured ? ' <span style="color:#B97A1D;">★ Mis en avant</span>' : '';
    return '<li style="margin-bottom:14px;">'
      + chip(cat) + ' <strong>' + esc(e.title) + '</strong>' + star + ' — ' + esc(e.venue) + ', ' + esc(e.city) + '<br>'
      + '<span style="margin-left:30px;">' + esc(e.dates_label) + '<br>'
      + esc(e.description)
      + (e.link ? ' <a href="' + e.link + '">En savoir plus</a>' : '')
      + '</span></li>';
  }).join('') + '</ul>';
}

const today = new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric' });
const legend = Object.values(CATEGORIES).map(c => chip(c) + ' ' + c.label).join(' &nbsp;&nbsp; ');

const html = '<h1 style="font-family:Arial,sans-serif;color:#2E2B27;">Newsletter Art &amp; Expos - Rennes &amp; Ille-et-Vilaine - ' + today + '</h1>'
  + '<p style="font-family:Arial,sans-serif;font-size:0.8em;line-height:2;">' + legend + '</p>'
  + '<p style="font-family:Arial,sans-serif;"><a href="https://penloup.eu/art-actu.php" style="display:inline-block;background:#2B2E33;color:#fff;padding:9px 16px;border-radius:6px;text-decoration:none;">Voir la carte interactive</a></p>'
  + '<h2 style="font-family:Arial,sans-serif;color:#2E2B27;">En ce moment</h2>' + renderList(enCours)
  + '<h2 style="font-family:Arial,sans-serif;color:#2E2B27;">A venir prochainement</h2>' + renderList(aVenir);

return [{ json: { html, exhibitions } }];

const today = $now.toFormat('dd/MM/yyyy');
const rawSites = ($('Lire liste de sites').item.json.data ?? $('Lire liste de sites').item.json ?? '').toString();
const sites = rawSites.split(/\r?\n/)
  .map(function (l) { return l.trim(); })
  .filter(function (l) { return l && !l.startsWith('#'); });
const sitesLine = sites.length
  ? ' Voici une liste de sites qui peuvent etre utiles (en plus de toute autre source pertinente si besoin) : ' + sites.join(', ') + '.'
  : '';

const prompt = 'Nous sommes le ' + today + '. Utilise la recherche web pour trouver specifiquement des evenements de STREET ART / ART URBAIN (murs peints, fresques murales, graffitis, interventions urbaines) qui, a la date d\'aujourd\'hui, sont soit deja visibles soit prevus dans les prochaines semaines, a Rennes et dans le departement Ille-et-Vilaine (35), en Bretagne, France. Ne cherche que du street art / art urbain, pas les autres formes d\'art.' + sitesLine + ' Pour chaque evenement distinct que tu retiens, ecris un paragraphe separe donnant : le nom de l\'evenement ou de la fresque, le nom exact du lieu ou l\'adresse, la ville, les dates si connues, une description en 1-2 phrases, et cite la page web qui te sert de source. Cherche en priorite la page dediee a cet evenement plutot que la page d\'accueil d\'un site. Verifie que chaque evenement est reel. Si tu ne trouves vraiment aucune information fiable de street art, dis-le simplement plutot que d\'inventer.';

const body = {
  model: 'gpt-4.1',
  tools: [{ type: 'web_search' }],
  input: prompt,
};

return [{ json: { body } }];

const response = $input.first().json;
const output = response.output || [];
let text = '';
let annotations = [];
for (const item of output) {
  if (item.type === 'message' && Array.isArray(item.content)) {
    for (const c of item.content) {
      if (c.type === 'output_text') {
        text = c.text || '';
        annotations = c.annotations || [];
      }
    }
  }
}

const sorted = annotations.filter(a => a.type === 'url_citation' && a.url).sort((a, b) => b.end_index - a.end_index);
for (const a of sorted) {
  const insert = ' (Source: ' + a.url + ')';
  text = text.slice(0, a.end_index) + insert + text.slice(a.end_index);
}

const previousText = $('Inserer citations dans le texte').item.json.annotated_text || '';
const combined = previousText + '\n\n--- Street art / art urbain ---\n\n' + text;

return [{ json: { annotated_text: combined } }];
